#!/usr/bin/env bash
set -euo pipefail
export FOUNDRY_PROFILE="${FOUNDRY_PROFILE:-default}"
ETHERSCAN_API_KEY="${ETHERSCAN_API_KEY:-${ETHERSCAN_V2_API_KEY:-}}"
if [ -z "$ETHERSCAN_API_KEY" ]; then echo "set ETHERSCAN_API_KEY (or ETHERSCAN_V2_API_KEY)"; exit 1; fi
CHAIN_ID=8453
VERIFIER_URL="${VERIFIER_URL:-https://api.etherscan.io/v2/api?chainid=8453}"

CHAIN_FLAG="--chain"
if forge verify-contract --help 2>/dev/null | grep -q -- "--chain-id"; then CHAIN_FLAG="--chain-id"; fi

PROFILE_FLAG=""
if forge verify-contract --help 2>/dev/null | grep -q -- "--compilation-profile"; then PROFILE_FLAG="--compilation-profile default"; fi

forge verify-contract 0x4A923eACBdF8Ca3571c5dbf4B182AEC5418736A6 src/adapters/chainlink/ChainlinkV2PlusWrapperAdapter.sol:ChainlinkV2PlusWrapperAdapter $CHAIN_FLAG $CHAIN_ID --watch --verifier etherscan --etherscan-api-key $ETHERSCAN_API_KEY $PROFILE_FLAG --verifier-url $VERIFIER_URL --constructor-args 0x000000000000000000000000b0407dbe851f8318bd31404a49e658143c982f23000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0xe441dF37b6c3717A4126d201D9130ffa65eC866D src/core/VRFHub.sol:VRFHub $CHAIN_FLAG $CHAIN_ID --watch --verifier etherscan --etherscan-api-key $ETHERSCAN_API_KEY $PROFILE_FLAG --verifier-url $VERIFIER_URL --constructor-args 0x0000000000000000000000004a923eacbdf8ca3571c5dbf4b182aec5418736a6000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x7E92e8C162c811fa8b676B7222844fe9a1005479 src/core/PoolRegistry.sol:PoolRegistry $CHAIN_FLAG $CHAIN_ID --watch --verifier etherscan --etherscan-api-key $ETHERSCAN_API_KEY $PROFILE_FLAG --verifier-url $VERIFIER_URL --constructor-args 0x000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0xd9d1B9f9D47922D776f5A4A05eeB4D5b802E05d7 src/core/SettlementRouter.sol:SettlementRouter $CHAIN_FLAG $CHAIN_ID --watch --verifier etherscan --etherscan-api-key $ETHERSCAN_API_KEY $PROFILE_FLAG --verifier-url $VERIFIER_URL --constructor-args 0x0000000000000000000000007e92e8c162c811fa8b676b7222844fe9a1005479
forge verify-contract 0x139F850D11f0FA6fbDbFA6c7024806bB822c336f src/engines/referral/ReferralRegistry.sol:ReferralRegistry $CHAIN_FLAG $CHAIN_ID --watch --verifier etherscan --etherscan-api-key $ETHERSCAN_API_KEY $PROFILE_FLAG --verifier-url $VERIFIER_URL --constructor-args 0x000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x1c7f605d39c66f64Fe6576d54e27A87825397A20 src/engines/referral/DefaultReferralEngine.sol:DefaultReferralEngine $CHAIN_FLAG $CHAIN_ID --watch --verifier etherscan --etherscan-api-key $ETHERSCAN_API_KEY $PROFILE_FLAG --verifier-url $VERIFIER_URL
