forge verify-contract 0x84e6d3db39E1b0e0386D8f4e3222926db32A75c9 src/modules/keno/KenoModule.sol:KenoModule $CHAIN_FLAG $CHAIN_ID --watch --verifier etherscan --etherscan-api-key $ETHERSCAN_API_KEY $PROFILE_FLAG --verifier-url $VERIFIER_URL
